// room: Home office (plan ROOMS, box [13,2,9,18,4,14]): quiet, studious, warm dark oak. Built only inside the box.
// Layout: a bookshelf wall on the west (x13) and a short east run (x18, z12..14); a desk under the north window (x14..16,
// z10) with a lectern (the focal piece) and a leather chair (dark_oak_stairs) at z11 facing north; a brown rug in front
// of the desk; a floor lamp in the NE corner; hanging lanterns for light. The French-door lane x18,z10..11 stays clear.
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { BOOKSHELF, BROWN_CARPET, LECTERN, BARREL } from "../vocab.mjs";

const put = (g, x, y, z, pair) => g.set(x, y, z, ...pair);
const block = (name) => [name, {}];

// French doors from the foyer: two open birch doors in the x19 wall (z10 and z11), lower and upper halves.
// Local helper: vocab's frenchDoor() is for a south-facing pair along x, and this pair runs along z.
function frenchDoors(g) {
  for (const [z, hinge] of [[10, "left"], [11, "right"]])
    for (const half of ["lower", "upper"]) {
      const y = half === "lower" ? 2 : 3;
      put(g, 19, y, z, ["birch_door", { facing: "west", half, hinge, open: "true", powered: "false" }]);
    }
}

export function build(g) {
  frenchDoors(g);
  // bookshelf wall: west side, full height (plan: a wall of bookshelves)
  for (let z = 9; z <= 14; z++) for (let y = 2; y <= 4; y++) put(g, 13, y, z, block(BOOKSHELF));
  // short east run, south of the French-door lane
  for (let z = 12; z <= 14; z++) for (let y = 2; y <= 3; y++) put(g, 18, y, z, block(BOOKSHELF));

  // desk facing the north window: fence legs under a dark oak slab top at y3, lectern centred on it
  for (let x = 14; x <= 16; x++) put(g, x, 2, 10, B.fence("dark_oak"));
  for (const x of [14, 16]) put(g, x, 3, 10, B.slab("dark_oak", "bottom"));
  put(g, 15, 3, 10, [LECTERN, { facing: "south", has_book: "false", powered: "false" }]);

  // leather chair (dark oak stairs) behind the desk, back to the south, facing the window
  put(g, 15, 2, 11, B.stairs("dark_oak", "south", "bottom"));

  // small rug in front of the desk
  for (let x = 14; x <= 16; x++) for (let z = 12; z <= 13; z++) put(g, x, 2, z, block(BROWN_CARPET));

  // hanging lanterns: one over the desk, one over the room's south-east corner
  put(g, 14, 4, 10, B.lantern(true));
  put(g, 17, 4, 13, B.lantern(true));

  // floor lamp: a lantern standing on a fence post in the NE corner (kept off the window strip x14..16,z9, which
  // stays reachable through x17,z9)
  put(g, 18, 2, 9, B.fence("dark_oak"));
  put(g, 18, 3, 9, B.lantern(false));

  // storage barrel in the SE corner
  put(g, 17, 2, 14, [BARREL, { facing: "up", open: "false" }]);
}
----ROOM12
// room: Bedroom 3 (plan ROOMS): inner air x27..32, y6..8, z9..14; floor = the y5 layer (oak_planks, shell).
// Guest/girl's room in pink and white. Entry: door (26,6..7,14) from the upper hall, so the way in is (27,6,14).
// Bay opening (30..32,6..8,8) to the turret nook: keep (30..32,6..8,9) clear. East window (33,7..8,10..11): nothing on
// (32,7..8,10..11). Layout: bed focal on the east wall (head against the wall, facing east), white/red rug in the
// middle, dresser (2 chests) and wardrobe (birch planks) on the west wall, a dressing table with a stool by the bay.
// Light: three hanging lanterns under the ceiling (y8), the brightest one over the bed.

const BOX = { x0: 27, y0: 6, z0: 9, x1: 32, y1: 8, z1: 14 };
const inBox = (x, y, z) => x >= BOX.x0 && x <= BOX.x1 && y >= BOX.y0 && y <= BOX.y1 && z >= BOX.z0 && z <= BOX.z1;

// Places one block only into air inside this room's box (earlier parts' blocks are locked).
function put(g, x, y, z, block, state = {}) {
  if (!inBox(x, y, z)) throw new Error(`room-12: ${x},${y},${z} is outside the room box`);
  if (!g.isAir(x, y, z)) return;
  g.set(x, y, z, block, state);
}

export function build(g) {
  // bed: white, head against the east wall, facing east (foot -> head); one bed = two cells along x
  put(g, 31, 6, 13, "white_bed", { facing: "east", part: "foot", occupied: "false" });
  put(g, 32, 6, 13, "white_bed", { facing: "east", part: "head", occupied: "false" });

  // bedside table: barrel with a potted plant (the pink note)
  put(g, 32, 6, 12, "barrel", { facing: "up", open: "false" });
  put(g, 32, 7, 12, "potted_azalea_bush");

  // rug: white carpet with a red centre
  put(g, 29, 6, 11, "red_carpet");
  for (let x = 28; x <= 30; x++)
    for (let z = 10; z <= 12; z++) put(g, x, 6, z, "white_carpet");

  // dresser: two chests on the west wall, fronts facing the room
  put(g, 27, 6, 9, "chest", { facing: "east", type: "single", waterlogged: "false" });
  put(g, 27, 6, 10, "chest", { facing: "east", type: "single", waterlogged: "false" });

  // wardrobe: a tall birch cabinet on the west wall, z11..12, three high
  for (let y = 6; y <= 8; y++)
    for (let z = 11; z <= 12; z++) put(g, 27, y, z, "birch_planks");

  // dressing table by the bay: slab table with a stool (stair facing east: back to the east, seat faces west)
  put(g, 28, 6, 9, "oak_slab", { type: "bottom", waterlogged: "false" });
  put(g, 29, 6, 9, "oak_stairs", { facing: "east", half: "bottom", shape: "straight", waterlogged: "false" });

  // lights: hanging lanterns from the ceiling, the brightest over the bed
  put(g, 31, 8, 12, "lantern", { hanging: "true", waterlogged: "false" });
  put(g, 28, 8, 12, "lantern", { hanging: "true", waterlogged: "false" });
  put(g, 29, 8, 10, "lantern", { hanging: "true", waterlogged: "false" });
}
----ROOM13
// room: Bedroom 3 bay (turret): the reading nook in the turret. Inner air x30..32, y6..8, z5..7; entered from bedroom 3
// through the open z8 row; N windows (30..32,7..8,4), side windows (29,7..8,6) and (33,7..8,6).
// Design: a window seat of oak stairs under the tall N windows (the focal piece, brightest light), white carpet cushions
// on it; a two-cell bookshelf on the west wall under a hanging lantern; a reading table (oak fence + oak slab top) with a
// lantern, and a stair chair facing it. The x31 column stays clear (no lantern over it), so the walk reaches the seat.
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const WHITE_CARPET = "white_carpet", BOOKSHELF = "bookshelf", OAK_FENCE = "oak_fence", OAK_SLAB = "oak_slab";

export function build(g) {
  // window seat: three oak stairs whose back is the north wall, facing south into the room (the seat front is z6)
  for (let x = 30; x <= 32; x++) g.set(x, 6, 5, ...B.stairs("oak", "south", "bottom"));
  // cushions: white carpet on the seat (the windows are at z4, so the cushion row is clear of them)
  for (let x = 30; x <= 32; x++) g.set(x, 7, 5, WHITE_CARPET, {});

  // small bookshelf: two cells on the west wall
  g.set(30, 6, 6, BOOKSHELF, {});
  g.set(30, 6, 7, BOOKSHELF, {});

  // reading table: fence post at y6, oak slab top half at y7 (table surface y8), a standing lantern on it
  g.set(32, 6, 6, OAK_FENCE, {});
  g.set(32, 7, 6, OAK_SLAB, { type: "top", waterlogged: "false" });
  g.set(32, 8, 6, ...B.lantern(false));

  // stair chair at the table, back to the doorway, facing north at the table
  g.set(32, 6, 7, ...B.stairs("oak", "north", "bottom"));

  // hanging lamp over the bookshelf, at the ceiling: its head cell (30,8,7) blocks no seat, table or path cell
  g.set(30, 8, 7, ...B.lantern(true));
}

