/** A tower through the roof (an elevator head, a belvedere): a hollow shaft, then a lantern, spire or flat cap. */
function tower(W, t, { y0, topY, mat, trim, g, o }) {
  const [w, dd] = Array.isArray(t.size) ? t.size : [t.size ?? 4, t.size ?? 4], [x0, z0] = t.at, x1 = x0 + w - 1, z1 = z0 + dd - 1;
  const m = materialOf(t.material ?? o.gable ?? "deepslate_bricks"), from = t.from ?? y0, top = t.top === undefined ? "lantern" : t.top;
  const yT = t.y ?? topY + (t.height ?? 3);
  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) for (let y = from; y <= yT; y++) {
    const edge = x === x0 || x === x1 || z === z0 || z === z1;
    W.put(x, y, z, edge ? [m.full, undefined] : ["air", undefined]);
